{
  "spec_element": "invariant",
  "proof_obligation": "bridge",
  "diagnosis": "The loop only tracks that all elements before lo are < key, but nothing about elements from the right side of the search space being >= key. At loop exit (lo==hi==n), the postcondition forall i :: n<=i<a.Length ==> a[i]>=key cannot be derived. The missing invariant is that all elements at or after hi are >= key. This holds at initiation (hi=a.Length, vacuously true), is preserved because sortedness implies that when a[mid]>=key we set hi:=mid and all elements from mid onward are >=key, and when a[mid]<key hi is unchanged. At exit lo==hi so the invariant gives exactly the needed postcondition.",
  "repair": "invariant forall i :: hi <= i < a.Length ==> a[i] >= key"
}
